// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CameraNetwork) predicate.CameraNetwork {
	return predicate.CameraNetwork(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CameraNetwork) predicate.CameraNetwork {
	return predicate.CameraNetwork(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CameraNetwork) predicate.CameraNetwork {
	return predicate.CameraNetwork(sql.NotPredicates(p))
}
